def s(r): return {k: r["urgency"].get(k) for k in r["fired"] if r["urgency"].get(k) in ("immediate","folded","same_day","urgent")}
def P(name, vals, **kw):
    r = run(vals, show=False, **kw)
    print(f"{name:42s} INT={r['interrupt']} via={r['metViaUnknown']} acts={len(r['interruptActions'])} | {s(r)} | gaps={ {k:v for k,v in r['gaps'].items() if k.startswith('DM-ACU')} }")
    return r
